Future<Uint8List> _raster(void Function(ui.Canvas) render) async {
  final recorder = ui.PictureRecorder();
  final canvas = ui.Canvas(recorder);
  render(canvas);
  final picture = recorder.endRecording();
  final image = await picture.toImage(256, 256);
  try {
    return (await image.toByteData(
      format: ui.ImageByteFormat.rawRgba,
    ))!.buffer.asUint8List();
  } finally {
    image.dispose();
    picture.dispose();
  }
}

const _body = [Point(7, 6), Point(6, 6), Point(5, 6), Point(5, 7), Point(5, 8)];

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  setUpAll(() async {
    final loader = FontLoader('NagaMono')
      ..addFont(
        Future.value(
          ByteData.sublistView(
            File('assets/fonts/JetBrainsMono-Regular.ttf').readAsBytesSync(),
          ),
        ),
      )
      ..addFont(
        Future.value(
          ByteData.sublistView(
            File('assets/fonts/JetBrainsMono-Bold.ttf').readAsBytesSync(),
          ),
        ),
      );
    await loader.load();
  });
  test('pre-optimization rasters: classic, modern and retro renderers', () async {
    final captured = <String, String>{};
    const update = bool.fromEnvironment('UPDATE_MONO_RASTERS');
    final monoFile = File('test/fixtures/mono_rasters.json');
    final mono = monoFile.existsSync()
        ? Map<String, String>.from(
            jsonDecode(monoFile.readAsStringSync()) as Map,
          )
        : <String, String>{};
    const tiles = 16;
    (List<int>, int, List<int>) profile(List<int> rgba) {
      final side = sqrt(rgba.length / 4).round();
      final tileSide = side ~/ tiles;
      final coverage = List<int>.filled(tiles * tiles, 0);
      var ink = 0;
      var minX = side, minY = side, maxX = -1, maxY = -1;
      for (var y = 0; y < side; y++) {
        for (var x = 0; x < side; x++) {
          if (rgba[(y * side + x) * 4 + 3] < 128) continue;
          ink++;
          coverage[(y ~/ tileSide) * tiles + (x ~/ tileSide)]++;
          if (x < minX) minX = x;
          if (y < minY) minY = y;
          if (x > maxX) maxX = x;
          if (y > maxY) maxY = y;
        }
      }
      return (coverage, ink, [minX, minY, maxX, maxY]);
    }

    void checkMono(String key, List<int> bytes, List<int> reference) {
      expect(bytes.length, reference.length, reason: '$key dimensions');
      final (coverage, ink, bounds) = profile(bytes);
      final (referenceCoverage, referenceInk, referenceBounds) = profile(
        reference,
      );
      expect(referenceInk, greaterThan(0), reason: '$key reference has ink');
      for (var i = 0; i < bounds.length; i++) {
        expect(
          (bounds[i] - referenceBounds[i]).abs(),
          lessThanOrEqualTo(2),
          reason: '$key ink bounds $bounds vs $referenceBounds',
        );
      }
      expect(
        (ink - referenceInk).abs(),
        lessThanOrEqualTo(max(64, (referenceInk * 0.15).ceil())),
        reason: '$key ink $ink vs $referenceInk',
      );
      // Raw ink totals differ per platform by a roughly constant factor that
      // reaches 6 to 7 percent, so compare normalized tile shares instead.
      for (var i = 0; i < coverage.length; i++) {
        expect(
          (coverage[i] / ink - referenceCoverage[i] / referenceInk).abs(),
          lessThanOrEqualTo(0.04),
          reason:
              '$key tile $i share ${coverage[i] / ink} vs '
              '${referenceCoverage[i] / referenceInk}',
        );
      }
    }

    Future<void> check(String key, void Function(ui.Canvas) render) async {
      final bytes = await _raster(render);
      captured[key] = base64Encode(zlib.encode(bytes));
      expect(_baselines, contains(key));
      // Every renderer that draws glyphs, including the Snake II maze label
      // that relies on the default family.
      final isMono =
          key.startsWith('ASCII-') ||
          key.startsWith('CGA-') ||
          key.startsWith('Nibbles-') ||
          key.startsWith('Snake II-');
      if (isMono && update) {
        mono[key] = captured[key]!;
      } else if (isMono) {
        // Glyph antialiasing is resolved by the host rasterizer and the retro
        // renderers band per-pixel alpha, so no byte or palette comparison can
        // hold across operating systems: the same input yields alpha 18, 17
        // and 0 at the same pixel on macOS, the macOS runner and Linux. These
        // renderers are compared structurally instead, which still fails on a
        // missing glyph, a shifted board or a resized cell. Shape-only
        // renderers below remain byte-exact.
        checkMono(key, bytes, zlib.decode(base64Decode(mono[key]!)));
      } else {
        expect(
          bytes,
          orderedEquals(zlib.decode(base64Decode(_baselines[key]!))),
          reason: key,
        );
      }
      expect(await _raster(render), orderedEquals(bytes), reason: '$key warm');
    }

    for (final mode in [ClassicMode(), ArcadeMode()]) {
      final game = SnakeGame(
        mode: mode,
        onGameOver: () {},
        onScoreChanged: (_) {},
      );
      final snake = Snake(game, initialSegments: _body);
      for (final cs in [14.0, 19.25, 14.0]) {
        game.cellSize = cs;
        game.boardOffset = Vector2(27, 38);
        for (final direction in Direction.values) {
          game.currentDirection = direction;
          await check('${mode.name}-$cs-${direction.name}', snake.render);
        }
      }
      game.boardOffset.x += 7;
      await check('${mode.name}-offset', snake.render);
      for (final buff in [
        PowerUpType.shield,
        PowerUpType.speed,
        PowerUpType.magnet,
        PowerUpType.slow,
      ]) {
        game.activeBuffs.clear();
        game.activeBuffs[buff] = 5;
        await check('${mode.name}-${buff.name}', snake.render);
      }
      for (final flash in [0.5, 0.17, 0.0]) {
        game.shieldFlashTimer = flash;
        await check('${mode.name}-flash-$flash', snake.render);
      }
      game.activeBuffs.clear();
      snake.segments = [const Point(5, 5)];
      await check('${mode.name}-single', snake.render);
      snake.segments.clear();
      await check('${mode.name}-empty', snake.render);
    }

    // No onLoad: avoid randomized food/maze initialization. Public fixture state
    // exercises real rendering, while score/size changes invalidate text caches.
    final games = <dynamic>[
      AsciiGame(
        mode: AsciiMode(),
        onGameOver: () {},
        onScoreChanged: (_) {},
        gridWidth: 10,
        gridHeight: 10,
      ),
      CgaGame(
        mode: CgaMode(),
        onGameOver: () {},
        onScoreChanged: (_) {},
        gridWidth: 10,
        gridHeight: 10,
      ),
      NibblesGame(
        mode: NibblesMode(),
        onGameOver: () {},
        onScoreChanged: (_) {},
        gridWidth: 10,
        gridHeight: 10,
      ),
      Snake2Game(
        mode: Snake2Mode(),
        onGameOver: () {},
        onScoreChanged: (_) {},
        gridWidth: 10,
        gridHeight: 10,
      ),
    ];
    for (final game in games) {
      game.onGameResize(Vector2(256, 256));
      game.snakeSegments = _body.toList();
      if (game is Snake2Game) {
        game.foodPositions = [const Point(2, 3), const Point(8, 2)];
        game.mazeWalls = [const Point(3, 3), const Point(3, 4)];
        game.bonusPosition = const Point(8, 8);
      } else {
        game.foodPosition = const Point<int>(2, 3);
      }
      for (final cs in [14.0, 19.25, 14.0]) {
        game.cellSize = cs;
        game.boardOffset = Vector2(27, 38);
        for (final score in [0, 123, 0]) {
          game.score = score;
          await check(
            '${game.mode.name}-$cs-$score',
            game.render as void Function(ui.Canvas),
          );
        }
      }
      game.boardOffset.y += 8;
      await check(
        '${game.mode.name}-offset',
        game.render as void Function(ui.Canvas),
      );
      game.onRemove();
    }
    expect(captured.keys.toSet(), _baselines.keys.toSet());
    expect(mono.length, 20);
    if (update) {
      monoFile.parent.createSync(recursive: true);
      monoFile.writeAsStringSync(
        '${const JsonEncoder.withIndent('  ').convert(mono)}\n',
      );
    }
  });
}
